}
$MaxHeaderBytes=32768;$MaxHeaderLines=100;$MaxBodyBytes=1048576;$IoTimeoutMs=10000
function Require-ExactProperties($Object,[string]$Context,[Parameter(ValueFromRemainingArguments=$true)][string[]]$Names){$actual=@($Object.PSObject.Properties.Name);if($actual.Count -ne $Names.Count-or @($actual|Where-Object {$_ -notin $Names}).Count){throw "$Context has unexpected or missing properties."}}
function Require-String($Value,[string]$Name){if($Value -isnot [string]){throw "$Name must be a string."};return [string]$Value}
function Require-Boolean($Value,[string]$Name){if($Value -isnot [bool]){throw "$Name must be a boolean."};return [bool]$Value}
function Require-Int64($Value,[string]$Name){if($Value -isnot [long] -and $Value -isnot [int]){throw "$Name must be an integer."};return [long]$Value}
function Test-NonReparseFile([string]$Path){$item=Get-Item -LiteralPath $Path -Force -ErrorAction SilentlyContinue;if($null-eq$item-or $item.PSIsContainer-or($item.Attributes-band [IO.FileAttributes]::ReparsePoint)){return $false};return $true}
function Get-Sha256([string]$Path){return ((Get-FileHash -LiteralPath $Path -Algorithm SHA256).Hash.ToUpperInvariant())}
function Require-EmptyExternalResultDirectory([string]$Path){if(-not[IO.Path]::IsPathRooted($Path)){throw 'ResultDirectory must be an explicit rooted path.'};$full=[IO.Path]::GetFullPath($Path).TrimEnd('\','/');$repository=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path.TrimEnd('\','/');if($full.Equals($root,[StringComparison]::OrdinalIgnoreCase)-or$full.StartsWith("$root\",[StringComparison]::OrdinalIgnoreCase)-or$full.Equals($repository,[StringComparison]::OrdinalIgnoreCase)-or$full.StartsWith("$repository\",[StringComparison]::OrdinalIgnoreCase)){throw 'ResultDirectory must be outside the immutable corpus and repository.'};$ancestor=$full;while(-not(Test-Path -LiteralPath $ancestor)){$parent=Split-Path -Parent $ancestor;if(!$parent-or$parent-eq$ancestor){throw 'ResultDirectory has no existing ancestor.'};$ancestor=$parent};while($true){$item=Get-Item -LiteralPath $ancestor -Force;if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){throw "ResultDirectory ancestor is a reparse-point: $ancestor"};$parent=Split-Path -Parent $ancestor;if(!$parent-or$parent-eq$ancestor){break};$ancestor=$parent};if(Test-Path -LiteralPath $full){$item=Get-Item -LiteralPath $full -Force;if(-not$item.PSIsContainer-or($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0-or[IO.Directory]::EnumerateFileSystemEntries($full).GetEnumerator().MoveNext()){throw 'ResultDirectory must be a new or empty non-reparse directory.'}}else{New-Item -ItemType Directory -Path $full|Out-Null};return $full}
function Assert-CorpusArtifactBinding($Binding,[string]$Name){if($Binding-isnot[pscustomobject]){throw "$Name binding must be an object."};Require-ExactProperties $Binding "$Name binding" 'path' 'length' 'sha256';$relative=Require-String $Binding.path "$Name path";if([IO.Path]::IsPathRooted($relative)-or$relative.Contains('..')){throw "$Name path is unsafe."};$candidate=[IO.Path]::GetFullPath((Join-Path $root $relative));if(-not$candidate.StartsWith("$root\",[StringComparison]::OrdinalIgnoreCase)-or-not(Test-NonReparseFile $candidate)){throw "$Name is absent, unsafe, or a reparse-point."};$length=Require-Int64 $Binding.length "$Name length";$hash=Require-String $Binding.sha256 "$Name sha256";if((Get-Item -LiteralPath $candidate).Length-ne$length-or(Get-Sha256 $candidate)-cne$hash){throw "$Name hash or length binding failed."};return $candidate}
function Get-HostOsIdentity{$environmentVersion=[Environment]::OSVersion.Version;$registry=Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction Stop;$build=[string]$registry.CurrentBuildNumber;if([string]::IsNullOrWhiteSpace($build)){$build=[string]$registry.CurrentBuild};$ubr=[string]$registry.UBR;if([string]::IsNullOrWhiteSpace([string]$registry.ProductName)-or[string]::IsNullOrWhiteSpace($build)-or[string]::IsNullOrWhiteSpace($ubr)){throw 'Exact Windows host identity is unavailable.'};return [ordered]@{environmentVersion=$environmentVersion.ToString();productName=[string]$registry.ProductName;displayVersion=[string]$registry.DisplayVersion;editionId=[string]$registry.EditionID;currentBuild=$build;ubr=$ubr;buildLabEx=[string]$registry.BuildLabEx}}
if(-not [IO.Path]::IsPathRooted($CorpusRoot)-or-not(Test-Path -LiteralPath $CorpusRoot -PathType Container)){throw 'CorpusRoot must be an existing explicit rooted directory.'}
$root=(Resolve-Path -LiteralPath $CorpusRoot).Path.TrimEnd('\','/');$indexPath=Join-Path $root 'index.html';$manifestPath=Join-Path $root 'manifest.json'
if(-not(Test-NonReparseFile $indexPath)-or-not(Test-NonReparseFile $manifestPath)){throw 'CorpusRoot must contain non-reparse index.html and manifest.json files.'}
try{$manifest=Get-Content -LiteralPath $manifestPath -Raw|ConvertFrom-Json -Depth 16}catch{throw "manifest.json is not valid JSON: $($_.Exception.Message)"}
Require-ExactProperties $manifest 'manifest' 'schemaVersion' 'kind' 'dispositionSummary' 'routes' 'blockedRoutes' 'limitations'
if((Require-Int64 $manifest.schemaVersion 'manifest.schemaVersion') -ne 2-or (Require-String $manifest.kind 'manifest.kind') -cne $ManifestKind){throw 'manifest.json has an unsupported kind or schemaVersion.'}
if($manifest.routes -isnot [array] -or $manifest.blockedRoutes -isnot [array]){throw 'manifest route dispositions must be arrays.'}
if($manifest.dispositionSummary-isnot[pscustomobject]){throw 'Manifest dispositionSummary must be an object.'};Require-ExactProperties $manifest.dispositionSummary 'manifest dispositionSummary' 'availableRouteCount' 'blockedRouteCount';if((Require-Int64 $manifest.dispositionSummary.availableRouteCount 'availableRouteCount')-ne$manifest.routes.Count-or(Require-Int64 $manifest.dispositionSummary.blockedRouteCount 'blockedRouteCount')-ne$manifest.blockedRoutes.Count){throw 'Manifest dispositionSummary does not match route arrays.'}
$allowedFiles=@{'index.html'=$indexPath;'manifest.json'=$manifestPath};$availableById=@{};$blockedById=@{};$seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal)
foreach($route in $manifest.routes){Require-ExactProperties $route 'manifest route' 'id' 'url' 'mime' 'videoOnly' 'sha256' 'length';$id=Require-String $route.id 'route.id';if(-not $ExpectedRoutes.Contains($id)-or-not $seen.Add($id)){throw 'manifest route IDs must be the exact four approved IDs once each.'};$expected=$ExpectedRoutes[$id];if((Require-String $route.url 'route.url') -cne $expected.url-or (Require-String $route.mime 'route.mime') -cne $expected.mime-or (Require-Boolean $route.videoOnly 'route.videoOnly') -ne $expected.videoOnly){throw "manifest route $id does not match the approved route definition."};$length=Require-Int64 $route.length 'route.length';$hash=Require-String $route.sha256 'route.sha256';if($length-lt 1-or$hash-notmatch '^[A-F0-9]{64}$'){throw "manifest route $id has invalid hash or length."};$mediaPath=Join-Path $root $expected.url;if(-not(Test-NonReparseFile $mediaPath)){throw "manifest route $id has no safe media file."};$item=Get-Item -LiteralPath $mediaPath;if($item.Length-ne$length-or(Get-Sha256 $mediaPath)-cne$hash){throw "manifest route $id media hash or length does not match manifest."};$allowedFiles[$expected.url]=$mediaPath;$availableById[$id]=$route}
foreach($blocked in $manifest.blockedRoutes){Require-ExactProperties $blocked 'blocked manifest route' 'id' 'status' 'reason' 'transformation';$id=Require-String $blocked.id 'blocked route id';if(-not$ExpectedRoutes.Contains($id)-or-not$seen.Add($id)){throw 'Blocked route IDs must be approved and unique.'};if((Require-String $blocked.status 'blocked route status')-cne'blocked'){throw 'Blocked manifest route has invalid status.'};[void](Require-String $blocked.reason 'blocked route reason');if($blocked.transformation-isnot[pscustomobject]){throw 'Blocked route transformation must be an object.'};Require-ExactProperties $blocked.transformation 'blocked route transformation' 'path' 'length' 'sha256';$path=Require-String $blocked.transformation.path 'blocked route transformation path';if($path-notmatch '^transformations/[A-Za-z0-9._-]+\.blocked\.json$'){throw 'Blocked route transformation path is invalid.'};$length=Require-Int64 $blocked.transformation.length 'blocked route transformation length';$hash=Require-String $blocked.transformation.sha256 'blocked route transformation sha256';$transformationPath=Join-Path $root $path;if(-not(Test-NonReparseFile $transformationPath)-or(Get-Item -LiteralPath $transformationPath).Length-ne$length-or(Get-Sha256 $transformationPath)-cne$hash){throw 'Blocked route transformation evidence is missing or has changed.'};$blockedById[$id]=$blocked}
if($seen.Count-ne$ExpectedRoutes.Count){throw 'Manifest must disposition each approved route exactly once.'}
$corpusEvidencePath=Join-Path $root 'g0.4-playback-corpus-evidence.json';if(-not(Test-NonReparseFile $corpusEvidencePath)){throw 'Corpus preparation evidence is missing or unsafe.'};try{$corpusEvidence=Get-Content -LiteralPath $corpusEvidencePath -Raw|ConvertFrom-Json -Depth 48}catch{throw 'Corpus preparation evidence is invalid JSON.'};if($corpusEvidence.schemaVersion-ne2-or$corpusEvidence.profileId-ne'P2.BtbnLgplShared.WindowsX64.20260820'-or$corpusEvidence.preflight.status-ne'passed'){throw 'Corpus preparation evidence does not bind the approved v2 P2 proof.'};if((Assert-CorpusArtifactBinding $corpusEvidence.manifest 'Corpus manifest')-cne$manifestPath-or(Assert-CorpusArtifactBinding $corpusEvidence.indexHtml 'Corpus index')-cne$indexPath){throw 'Corpus preparation evidence does not bind manifest.json and index.html.'};$bound=@($corpusEvidence.boundArtifacts);$boundPaths=@($bound|ForEach-Object path);if($bound.Count-eq0-or@($boundPaths|Sort-Object -Unique).Count-ne$bound.Count){throw 'Corpus bound-artifact closure is missing or duplicates a path.'};foreach($binding in $bound){Assert-CorpusArtifactBinding $binding 'Corpus bound artifact'|Out-Null};$actual=@([IO.Directory]::EnumerateFiles($root,'*',[IO.SearchOption]::AllDirectories)|ForEach-Object{[IO.Path]::GetRelativePath($root,$_).Replace('\','/')}|Where-Object{$_-notin@('manifest.json','g0.4-playback-corpus-evidence.json')}|Sort-Object);if(@(Compare-Object $actual @($boundPaths|Sort-Object)).Count-ne0){throw 'Corpus bound-artifact provenance does not exactly cover the immutable corpus.'};$hostOs=Get-HostOsIdentity;$serverScript=[ordered]@{path=$PSCommandPath;length=(Get-Item -LiteralPath $PSCommandPath).Length;sha256=Get-Sha256 $PSCommandPath};$corpusBinding=[ordered]@{root=$root;manifest=[ordered]@{path='manifest.json';length=(Get-Item -LiteralPath $manifestPath).Length;sha256=Get-Sha256 $manifestPath};preparationEvidence=[ordered]@{path='g0.4-playback-corpus-evidence.json';length=(Get-Item -LiteralPath $corpusEvidencePath).Length;sha256=Get-Sha256 $corpusEvidencePath};indexHtml=[ordered]@{path='index.html';length=(Get-Item -LiteralPath $indexPath).Length;sha256=Get-Sha256 $indexPath}}
$results=Require-EmptyExternalResultDirectory $ResultDirectory
function Read-AsciiLine([IO.Stream]$Stream,[int]$Limit){$bytes=[Collections.Generic.List[byte]]::new();while($true){$next=$Stream.ReadByte();if($next-lt 0){if($bytes.Count-eq 0){return $null};throw 'Unexpected end of request.'};if($next-eq 10){if($bytes.Count-gt 0-and$bytes[$bytes.Count-1]-eq 13){$bytes.RemoveAt($bytes.Count-1)};return [Text.Encoding]::ASCII.GetString($bytes.ToArray())};if($bytes.Count-ge$Limit){throw 'Request line or header is too large.'};$bytes.Add([byte]$next)}}
function Read-ExactBytes([IO.Stream]$Stream,[int]$Length){$bytes=New-Object byte[] $Length;$offset=0;while($offset-lt$Length){$read=$Stream.Read($bytes,$offset,$Length-$offset);if($read-le 0){throw 'Unexpected end of request body.'};$offset+=$read};return $bytes}
function Write-Response([IO.Stream]$Stream,[int]$Status,[string]$Reason,[hashtable]$Headers,[byte[]]$Body,[bool]$Head,[long]$ContentLength=$Body.Length){$header="HTTP/1.1 $Status $Reason`r`nConnection: close`r`n";foreach($key in $Headers.Keys){$header+="${key}: $($Headers[$key])`r`n"};$header+="Content-Length: $ContentLength`r`n`r`n";$wire=[Text.Encoding]::ASCII.GetBytes($header);$Stream.Write($wire,0,$wire.Length);if(-not$Head-and$Body.Length){$Stream.Write($Body,0,$Body.Length)}}
function Write-Error([IO.Stream]$Stream,[int]$Status,[string]$Reason,[bool]$Head,[hashtable]$Headers=@{}){Write-Response $Stream $Status $Reason $Headers ([byte[]]@()) $Head 0}
function Get-Range([string]$Value,[long]$Length){if($Value-notmatch '^bytes=(\d*)-(\d*)$'-or($Matches[1].Length-eq 0-and$Matches[2].Length-eq 0)){return $null};try{if($Matches[1].Length-eq 0){$suffix=[long]$Matches[2];if($suffix-le 0){return $null};$count=[Math]::Min($suffix,$Length);return ,([long[]]@(($Length-$count),($Length-1)))};$start=[long]$Matches[1];$end=if($Matches[2].Length){[long]$Matches[2]}else{$Length-1};if($start-ge$Length-or$end-lt$start){return $null};return ,([long[]]@($start,([Math]::Min($end,($Length-1)))))}catch{return $null}}
function Test-Observation($Json){
 Require-ExactProperties $Json 'observation' 'schemaVersion' 'kind' 'startedAt' 'userAgent' 'platform' 'highEntropyIdentity' 'routes' 'limitations' 'status'
 if((Require-Int64 $Json.schemaVersion 'observation.schemaVersion')-ne 2-or(Require-String $Json.kind 'observation.kind')-cne$ObservationKind){throw 'Observation has unsupported kind or schemaVersion.'}
 foreach($name in 'startedAt','userAgent','platform','highEntropyIdentity','limitations'){[void](Require-String $Json.$name "observation.$name")};$status=Require-String $Json.status 'observation.status';if($status-notin @('passed','failed','completed-with-inherited-blocked-routes')){throw 'Observation status is invalid.'};if($Json.routes-isnot[array]-or$Json.routes.Count-ne$ExpectedRoutes.Count){throw 'Observation must contain the exact four route dispositions.'}
 $seen=[Collections.Generic.HashSet[string]]::new([StringComparer]::Ordinal);$routeNames=@('id','status','reason','transformation','mime','videoOnly','userAgent','platform','canPlayType','metadata','firstAdvance','pauseStable','midpointSeek','resumeAdvance','replayAdvance','endedCount','events','error')
 foreach($route in $Json.routes){$actual=@($route.PSObject.Properties.Name);if(@($actual|Where-Object {$_-notin$routeNames}).Count){throw 'Observation route has an unknown property.'};$id=Require-String $route.id 'observation route id';if(-not$ExpectedRoutes.Contains($id)-or-not$seen.Add($id)){throw 'Observation route IDs must be exact and unique.'};$rs=Require-String $route.status 'observation route status';if($rs-notin @('passed','failed','blocked')){throw 'Observation route status is invalid.'};if($rs-eq'blocked'){foreach($required in 'reason','transformation'){if(-not$route.PSObject.Properties[$required]){throw 'Blocked result lacks source disposition provenance.'}};if(-not$blockedById.ContainsKey($id)){throw 'Available route cannot be submitted as blocked.'};if((Require-String $route.reason 'blocked route reason')-cne$blockedById[$id].reason){throw 'Blocked result reason differs from source disposition.'};if($route.transformation-isnot[pscustomobject]){throw 'Blocked route transformation must be an object.'};Require-ExactProperties $route.transformation 'blocked result transformation' 'path' 'length' 'sha256';if(($route.transformation|ConvertTo-Json -Compress)-cne($blockedById[$id].transformation|ConvertTo-Json -Compress)){throw 'Blocked result transformation differs from source disposition.'};continue};if(-not$availableById.ContainsKey($id)){throw 'Source-blocked route cannot be submitted as passed or failed.'};if($rs-eq'failed'){if(-not$route.PSObject.Properties['error']){throw 'Failed observation route must include error.'};[void](Require-String $route.error 'observation route error');continue};foreach($required in @('mime','videoOnly','userAgent','platform','canPlayType','metadata','firstAdvance','pauseStable','midpointSeek','resumeAdvance','replayAdvance','endedCount','events')){if(-not$route.PSObject.Properties[$required]){throw "Passed observation route is missing $required."}};if((Require-String $route.mime 'route.mime')-cne$ExpectedRoutes[$id].mime-or(Require-Boolean $route.videoOnly 'route.videoOnly')-ne$ExpectedRoutes[$id].videoOnly){throw 'Passed observation route does not match corpus.'};foreach($name in 'userAgent','platform','canPlayType'){[void](Require-String $route.$name "route.$name")};if($route.metadata-isnot[pscustomobject]){throw 'route.metadata must be an object.'};Require-ExactProperties $route.metadata 'route.metadata' 'width' 'height' 'duration';foreach($name in 'width','height','duration'){if($route.metadata.$name-isnot[int]-and$route.metadata.$name-isnot[long]-and$route.metadata.$name-isnot[double]){throw "route.metadata.$name must be numeric."}};foreach($name in 'firstAdvance','midpointSeek','resumeAdvance','replayAdvance','endedCount'){if($route.$name-isnot[int]-and$route.$name-isnot[long]-and$route.$name-isnot[double]){throw "route.$name must be numeric."}};[void](Require-Boolean $route.pauseStable 'route.pauseStable');if($route.events-isnot[array]){throw 'route.events must be an array.'}};$failedCount=@($Json.routes|Where-Object {$_.status -eq 'failed'}).Count;$blockedCount=@($Json.routes|Where-Object {$_.status -eq 'blocked'}).Count;$expectedStatus=if($failedCount-gt0){'failed'}elseif($blockedCount-gt0){'completed-with-inherited-blocked-routes'}else{'passed'};if($status-cne$expectedStatus){throw 'Observation top-level status does not match its route dispositions.'}
}
function Get-Mime([string]$Target){if($Target.EndsWith('.mp4')){'video/mp4'}elseif($Target.EndsWith('.webm')){'video/webm'}elseif($Target.EndsWith('.json')){'application/json; charset=utf-8'}else{'text/html; charset=utf-8'}}
$listener=[Net.Sockets.TcpListener]::new([Net.IPAddress]::Loopback,$Port);$listener.Start();$actualPort=([Net.IPEndPoint]$listener.LocalEndpoint).Port;Write-Output "Serving G0.4 playback corpus at http://127.0.0.1:$actualPort/ (Ctrl+C to stop)."
try{while($true){$client=$listener.AcceptTcpClient();try{$client.ReceiveTimeout=$IoTimeoutMs;$client.SendTimeout=$IoTimeoutMs;$stream=$client.GetStream();$first=Read-AsciiLine $stream $MaxHeaderBytes;if([string]::IsNullOrWhiteSpace($first)){continue};$parts=$first.Split(' ');if($parts.Count-ne 3){Write-Error $stream 400 'Bad Request' $false;continue};$method,$target=$parts[0],$parts[1];$head=$method-eq 'HEAD';$headers=@{};$headerBytes=$first.Length;for($i=0;$i-lt$MaxHeaderLines;$i++){$line=Read-AsciiLine $stream $MaxHeaderBytes;if($null-eq$line){throw 'Unexpected end of headers.'};if($line-eq''){break};$headerBytes+=$line.Length;if($headerBytes-gt$MaxHeaderBytes){throw 'Headers too large.'};$colon=$line.IndexOf(':');if($colon-le 0){throw 'Malformed header.'};$name=$line.Substring(0,$colon).Trim().ToLowerInvariant();if($headers.ContainsKey($name)){throw 'Duplicate header.'};$headers[$name]=$line.Substring($colon+1).Trim();if($i-eq($MaxHeaderLines-1)){throw 'Too many headers.'}}
if($method-eq'POST'-and$target-eq'/results'){$hasLength=$headers.ContainsKey('content-length');if($headers.ContainsKey('transfer-encoding')-or-not$hasLength){Write-Error $stream 411 'Length Required' $false;continue};if($headers['content-length']-notmatch '^\d+$'){Write-Error $stream 400 'Bad Request' $false;continue};try{$length=[long]$headers['content-length']}catch{Write-Error $stream 413 'Payload Too Large' $false;continue};if($length-gt$MaxBodyBytes){Write-Error $stream 413 'Payload Too Large' $false;continue};try{$body=Read-ExactBytes $stream ([int]$length);$text=[Text.UTF8Encoding]::new($false,$true).GetString($body);$json=$text|ConvertFrom-Json -Depth 32 -DateKind String;Test-Observation $json;$envelope=[ordered]@{schemaVersion=1;kind='ReelForge Gate 0 retained native playback observation envelope';savedAtUtc=[DateTimeOffset]::UtcNow.ToString('O');corpus=$corpusBinding;server=[ordered]@{script=$serverScript;hostOs=$hostOs;transport='loopback HTTP/1.1 TcpListener with validated single-byte-range support'};observation=$json};$canonical=$envelope|ConvertTo-Json -Compress -Depth 48}catch{$message=$_.Exception.Message;Write-Warning "Rejected playback observation: $message";$problem=[Text.Encoding]::UTF8.GetBytes((@{status='rejected';error=$message}|ConvertTo-Json -Compress));Write-Response $stream 400 'Bad Request' @{'Content-Type'='application/json; charset=utf-8'} $problem $false;continue};$name=('playback-observation-'+[DateTime]::UtcNow.ToString('yyyyMMddTHHmmssfffZ')+'-'+[Guid]::NewGuid().ToString('N')+'.json');$partial=Join-Path $results ('.partial-'+$name);$final=Join-Path $results $name;[IO.File]::WriteAllText($partial,$canonical,[Text.UTF8Encoding]::new($false));[IO.File]::Move($partial,$final);$reply=[Text.Encoding]::UTF8.GetBytes(('{"status":"saved-local-only","filename":"'+$name+'"}'));Write-Response $stream 201 'Created' @{'Content-Type'='application/json; charset=utf-8'} $reply $false;continue}
if($method-notin @('GET','HEAD')){Write-Error $stream 405 'Method Not Allowed' $head @{'Allow'='GET, HEAD, POST'};continue};if($target-notmatch '^/[^?#]*$'){Write-Error $stream 404 'Not Found' $head;continue};$raw=[uri]::UnescapeDataString($target.TrimStart('/'));if([string]::IsNullOrEmpty($raw)){$raw='index.html'};if($raw.Contains('..')-or-not$allowedFiles.ContainsKey($raw)){Write-Error $stream 404 'Not Found' $head;continue};$path=$allowedFiles[$raw];$length=(Get-Item -LiteralPath $path).Length;$headersOut=@{'Content-Type'=(Get-Mime $raw);'Accept-Ranges'='bytes'};$start=0L;$end=$length-1;$status=200;$reason='OK';if($headers.ContainsKey('range')){$range=Get-Range $headers['range'] $length;if($null-eq$range){Write-Error $stream 416 'Range Not Satisfiable' $head @{'Content-Range'="bytes */$length";'Accept-Ranges'='bytes'};continue};$start=[long]$range[0];$end=[long]$range[1];$status=206;$reason='Partial Content';$headersOut['Content-Range']="bytes $start-$end/$length"};$count=$end-$start+1;$body=if($head){[byte[]]@()}else{$file=[IO.File]::OpenRead($path);try{$file.Seek($start,[IO.SeekOrigin]::Begin)|Out-Null;Read-ExactBytes $file ([int]$count)}finally{$file.Dispose()}};Write-Response $stream $status $reason $headersOut $body $head $count
}catch{try{Write-Error $stream 400 'Bad Request' $false}catch{}}finally{$client.Close()}}}finally{$listener.Stop()}
